            continue
        man = abs(nx - ox) + abs(ny - oy)
        cheb = max(abs(nx - ox), abs(ny - oy))
        v1 = -man if pursuer else man
        v2 = -cheb if pursuer else cheb
        # tiebreak: prefer moving (avoid staying) when equal
        move_pref = 0 if (dx == 0 and dy == 0) else 1
